async function getMarkerFromUser(center, title, app, plugin, settings, customInstuctions = []) {
    return new Promise((resolve) => {
        const dialog = new MarkerSelectDialog(app, plugin, settings, (selection, evt) => {
            if (selection && selection.layer) {
                resolve([selection.layer, evt]);
            }
            else {
                resolve(null);
            }
        }, title, center, customInstuctions);
        dialog.open();
    });
}
class MarkerSelectDialog extends obsidian.SuggestModal {
    plugin;
    settings;
    sortByCenter;
    // If dialogAction is 'custom', this will launch upon selection
    customOnSelect;
    constructor(app, plugin, settings, action, title, sortByCenter = null, customInstuctions = []) {
        super(app);
        this.plugin = plugin;
        this.settings = settings;
        this.customOnSelect = action;
        this.sortByCenter = sortByCenter;
        this.setPlaceholder(title);
        let instructions = [{ command: 'enter', purpose: 'to use' }].concat(customInstuctions);
        this.setInstructions(instructions);
        this.inputEl.addEventListener('keypress', (ev) => {
            // In the case of a custom select function, trigger it also for Shift+Enter.
            // Obsidian doesn't have an API for that, so we find the selected item in a rather patchy way,
            // and manually close the dialog
            if (ev.key == 'Enter' &&
                ev.shiftKey &&
                this.customOnSelect != null) {
                const chooser = this.chooser;
                const selectedItem = chooser?.selectedItem;
                const values = chooser?.values;
                if (chooser && values) {
                    this.onChooseSuggestion(values[selectedItem], ev);
                    this.close();
                }
            }
        });
    }
    getSuggestions(query) {
        let results = [];
        for (const layer of this.plugin.layerCache.layers) {
            if (layer.name.toLowerCase().includes(query.toLowerCase()) &&
                layer instanceof FileMarker) {
                results.push({ layer });
            }
        }
        if (this.sortByCenter) {
            results.sort((a, b) => a.layer.location.distanceTo(this.sortByCenter) -
                b.layer.location.distanceTo(this.sortByCenter));
        }
        return results.slice(0, MAX_QUERY_SUGGESTIONS);
    }
    renderSuggestion(value, el) {
        el.addClass('map-search-suggestion');
        el.appendText(value.layer.name);
    }
    onChooseSuggestion(value, evt) {
        this.customOnSelect(value, evt);
    }
}

/** A class to convert a string (usually a URL) into geolocation format */
class UrlConvertor {
    settings;
    app;
    constructor(app, settings) {
        this.settings = settings;
        this.app = app;
    }
    /**
     * Parse the current editor line using the user defined URL parsers.
     * Returns leaflet.LatLng on success and null on failure.
     * @param editor The Obsidian Editor instance to use
     */
    hasMatchInLine(editor) {
        const cursor = editor.getCursor();
        const result = this.parseLocationFromUrl(editor.getLine(cursor.line));
        return result != null;
    }
    /**
     * Get geolocation from an encoded string (a URL, a lat,lng string or a URL to parse).
     * Will try each url parsing rule until one succeeds.
     * The returned value can either be a parsed & ready geolocation, or it can be a promise that still needs
     * to be resolved in the background (in the case of parsing a URL).
     * To just check if the line contains a string that can be parsed, the result can be compared to null,
     * but to use the value, you must await in case it's a Promise.
     * @param line The string to decode
     */
    parseLocationFromUrl(line) {
        for (const rule of this.settings.urlParsingRules) {
            const regexp = RegExp(rule.regExp, 'g');
            const results = line.matchAll(regexp);
            for (let result of results) {
                try {
                    if (rule.ruleType === 'fetch') {
                        const url = result[1];
                        if (!url || url.length <= 0)
                            continue;
                        return this.parseGeolocationWithFetch(url, rule, result.index, result[0].length);
                    }
                    else {
                        return {
                            location: rule.ruleType === 'latLng'
                                ? new leafletSrcExports.LatLng(parseFloat(result[1]), parseFloat(result[2]))
                                : new leafletSrcExports.LatLng(parseFloat(result[2]), parseFloat(result[1])),
                            index: result.index,
                            matchLength: result[0].length,
                            ruleName: rule.name,
                        };
                    }
                }
                catch (e) { }
            }
        }
        return null;
    }
    async parseGeolocationWithFetch(url, rule, userTextMatchIndex, userTextMatchLength) {
        const urlContent = await obsidian.request({ url: url });
        if (this.settings.debug)
            console.log('Fetch result for URL', url, ':', urlContent);
        const contentMatch = urlContent.match(rule.contentParsingRegExp);
        if (!contentMatch)
            return null;
        let geolocation = null;
        // TODO: Experimental, possibly unfinished code!
        if (rule.contentType === 'latLng' && contentMatch.length > 2)
            geolocation = new leafletSrcExports.LatLng(parseFloat(contentMatch[1]), parseFloat(contentMatch[2]));
        else if (rule.contentType === 'lngLat' && contentMatch.length > 2)
            geolocation = new leafletSrcExports.LatLng(parseFloat(contentMatch[2]), parseFloat(contentMatch[1]));
        else if (rule.contentType === 'googlePlace') {
            const placeName = contentMatch[1];
            if (this.settings.debug)
                console.log('Google Place search:', placeName);
            // TODO work in progress
            // const places = await googlePlacesSearch(placeName, this.settings);
            // if (places && places.length > 0) geolocation = places[0].location;
        }
        if (geolocation)
            return {
                location: geolocation,
                index: userTextMatchIndex,
                matchLength: userTextMatchLength,
                ruleName: rule.name,
            };
    }
    async getGeolocationFromGoogleLink(url, settings) {
        const content = await obsidian.request({ url: url });
        if (this.settings.debug)
            console.log('Google link: searching url', url);
        const placeNameMatch = content.match(/<meta content="([^\"]*)" itemprop="name">/);
        if (placeNameMatch) {
            const placeName = placeNameMatch[1];
            if (this.settings.debug)
                console.log('Google link: found place name = ', placeName);
            const googleApiKey = settings.geocodingApiKey;
            const params = {
                query: placeName,
                key: googleApiKey,
            };
            const googleUrl = 'https://maps.googleapis.com/maps/api/place/textsearch/json?' +
                queryString.stringify(params);
            const googleContent = await obsidian.request({ url: googleUrl });
            const jsonContent = JSON.parse(googleContent);
            if (jsonContent &&
                'results' in jsonContent &&
                jsonContent?.results.length > 0) {
                const location = jsonContent.results[0].location;
                if (location && location.lat && location.lng)
                    return new leafletSrcExports.LatLng(location.lat, location.lng);
            }
        }
        return null;
    }
    /**
     * Replace the text at the cursor location with a geo link
     * @param editor The Obsidian Editor instance
     */
    async convertUrlAtCursorToGeolocation(editor, file) {
        const cursor = editor.getCursor();
        const result = this.parseLocationFromUrl(editor.getLine(cursor.line));
        let geolocation;
        if (result instanceof Promise)
            geolocation = await result;
        else
            geolocation = result;
        if (geolocation)
            insertLocationToEditor(this.app, geolocation.location, editor, file, this.settings, { line: cursor.line, ch: geolocation.index }, geolocation.matchLength);
    }
}

function addShowOnMap(menu, geolocation, file, editorLine, plugin, settings, markerIdToHighlight = null) {
    if (geolocation) {
        menu.addItem((item) => {
            item.setTitle('Show on map');
            item.setSection('mapview');
            item.setIcon('globe');
            const openFunc = async (evt) => await plugin.openMapWithLocation(geolocation, mouseEventToOpenMode(settings, evt, 'openMap'), file, editorLine, evt.shiftKey, markerIdToHighlight);
            item.onClick(openFunc);
            addPatchyMiddleClickHandler(item, menu, openFunc);
        });
    }
}
